Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="layerStep">CLIP layer: Input (L0)</button>
<button id="branchToggle">Branches: Both</button>
<span style="font-weight:bold;font-size:11px;margin-top:4px;">Demo steps:</span>
<button id="demo0">Input layouts differ</button>
<button id="demo1">Mid-network drift</button>
<button id="demo2">Converged at the top</button>
<button id="demo3">One modality alone</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ──
// planes → LineLoop rect #333 + LineSegments grid #ccc, 2.2×1.2 in XY at Y=0,2,4,6,8
// markers → SphereGeometry(0.07) circle, BoxGeometry(0.11,0.11,0.02) square, ConeGeometry(0.07,0.12,3) triangle
// text labels → addLabel radially placed outside each text plane + leader Line #999
// trajectories → Line with LineDashedMaterial per concept per branch
// arrows → CylinderGeometry shaft + ConeGeometry head, black, between planes
// boxes → Sprite canvas rounded-rect + text, offset outward from planes
// orange disk → CircleGeometry(0.7) #f4a07a + RingGeometry rim black
// side rules → Line vertical + vertical-text canvas sprite at far left/right
// heading → addLabel bold above disk

const CONCEPTS = [
  { name: 'red circle', color: 0xe04040, shape: 'circle' },
  { name: 'green square', color: 0x4caf6e, shape: 'square' },
  { name: 'purple triangle', color: 0x9b59b6, shape: 'triangle' },
  { name: 'blue triangle', color: 0x4aa3df, shape: 'triangle' },
  { name: 'pink square', color: 0xf48fb1, shape: 'square' },
  { name: 'blue circle', color: 0x4aa3df, shape: 'circle' },
  { name: 'purple circle', color: 0x9b59b6, shape: 'circle' },
  { name: 'orange circle', color: 0xf0a050, shape: 'circle' },
  { name: 'pink circle', color: 0xf48fb1, shape: 'circle' },
];

const ALIGNED = [
  [-0.6, 0.5], [0.6, 0.6], [-0.5, -0.5], [0.7, -0.4], [0.1, 0.7],
  [-0.2, 0.1], [-0.7, 0.0], [0.3, 0.0], [0.0, -0.6]
];

const LAYER_Y = [0, 2.0, 4.0, 6.0, 8.0];
const IMG_X = -3.2, TXT_X = 3.2;
const PLANE_HW = 1.1, PLANE_HH = 0.6; // half-width, half-height of plane rect

function mulberry32(a) {
  return function() {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}
const rngImg = mulberry32(42);
const rngTxt = mulberry32(137);

const imgScatter = CONCEPTS.map(() => [(rngImg() * 2 - 1) * 0.85, (rngImg() * 2 - 1) * 0.85]);
const txtScatter = CONCEPTS.map(() => [(rngTxt() * 2 - 1) * 0.85, (rngTxt() * 2 - 1) * 0.85]);

// Concept position on plane: lerp(scatter, aligned, t/4) mapped to plane coords
function conceptPos(i, t, branchX, scatter) {
  const frac = t / 4;
  const u = scatter[i][0] + (ALIGNED[i][0] - scatter[i][0]) * frac;
  const v = scatter[i][1] + (ALIGNED[i][1] - scatter[i][1]) * frac;
  return new THREE.Vector3(branchX + u * PLANE_HW, LAYER_Y[t] + v * PLANE_HH, 0);
}

// Radial label position for text branch (outside the plane rectangle)
function labelPos(i, t) {
  const angle = (i / CONCEPTS.length) * Math.PI * 2 - Math.PI / 2;
  const rx = 1.7, ry = 0.95;
  return new THREE.Vector3(TXT_X + Math.cos(angle) * rx, LAYER_Y[t] + Math.sin(angle) * ry, 0);
}

// ── Groups ─
const imgGroup = new THREE.Group();
const txtGroup = new THREE.Group();
scene.add(imgGroup);
scene.add(txtGroup);

// ── Planes (rectangles in XY plane) ──
function makePlane(branchX, y, group) {
  const hw = PLANE_HW, hh = PLANE_HH;
  const pts = [
    new THREE.Vector3(branchX - hw, y - hh, 0),
    new THREE.Vector3(branchX + hw, y - hh, 0),
    new THREE.Vector3(branchX + hw, y + hh, 0),
    new THREE.Vector3(branchX - hw, y + hh, 0),
  ];
  const loop = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x333333, linewidth: 2 })
  );
  group.add(loop);
  // Inner grid: 2 lines (vertical center, horizontal center)
  const gridPts = [
    new THREE.Vector3(branchX, y - hh, 0), new THREE.Vector3(branchX, y + hh, 0),
    new THREE.Vector3(branchX - hw, y, 0), new THREE.Vector3(branchX + hw, y, 0),
  ];
  const grid = new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(gridPts),
    new THREE.LineBasicMaterial({ color: 0xcccccc })
  );
  group.add(grid);
}

for (let t = 0; t < 5; t++) {
  makePlane(IMG_X, LAYER_Y[t], imgGroup);
  makePlane(TXT_X, LAYER_Y[t], txtGroup);
}

// ── Image markers ──
const imgMarkers = [];
for (let i = 0; i < CONCEPTS.length; i++) {
  imgMarkers[i] = [];
  for (let t = 0; t < 5; t++) {
    const pos = conceptPos(i, t, IMG_X, imgScatter);
    const c = CONCEPTS[i];
    let geom;
    if (c.shape === 'circle') geom = new THREE.SphereGeometry(0.07, 12, 8);
    else if (c.shape === 'square') geom = new THREE.BoxGeometry(0.11, 0.11, 0.02);
    else geom = new THREE.ConeGeometry(0.07, 0.12, 3);
    const mat = new THREE.MeshBasicMaterial({ color: c.color, transparent: true, opacity: 1 });
    const mesh = new THREE.Mesh(geom, mat);
    mesh.position.copy(pos);
    mesh.userData = { conceptIdx: i, layer: t, branch: 'image' };
    imgGroup.add(mesh);
    imgMarkers[i][t] = mesh;
    registerInteractive(mesh, {
      title: c.name,
      tooltip: `Image: ${c.name} at layer ${t}`,
      body: `The "${c.name}" embedding at layer ${t} of the image encoder.`
    });
  }
}

// ── Text labels (addLabel, radially placed) + leader lines ──
const txtLabels = [];
const txtLeaderLines = [];
for (let i = 0; i < CONCEPTS.length; i++) {
  txtLabels[i] = [];
  txtLeaderLines[i] = [];
  for (let t = 0; t < 5; t++) {
    const mPos = conceptPos(i, t, TXT_X, txtScatter);
    const lPos = labelPos(i, t);
    // Leader line from label to marker position
    const lineGeom = new THREE.BufferGeometry().setFromPoints([lPos, mPos]);
    const lineMat = new THREE.LineBasicMaterial({ color: 0x999999, transparent: true, opacity: 0.5 });
    const line = new THREE.Line(lineGeom, lineMat);
    txtGroup.add(line);
    txtLeaderLines[i][t] = line;
    // Small dot at marker position on text plane
    const dotGeom = new THREE.SphereGeometry(0.04, 8, 6);
    const dotMat = new THREE.MeshBasicMaterial({ color: 0x666666, transparent: true, opacity: 1 });
    const dot = new THREE.Mesh(dotGeom, dotMat);
    dot.position.copy(mPos);
    dot.userData = { conceptIdx: i, layer: t, branch: 'text' };
    txtGroup.add(dot);
    registerInteractive(dot, {
      title: CONCEPTS[i].name,
      tooltip: `Text: "${CONCEPTS[i].name}" at layer ${t}`,
      body: `The text embedding "${CONCEPTS[i].name}" at layer ${t} of the text encoder.`
    });
    // HTML label
    const lbl = addLabel(CONCEPTS[i].name, lPos, { fontSize: '10px', color: '#333' });
    txtLabels[i][t] = { entry: lbl, dot };
  }
}

// ── Trajectories (dashed lines) ──
const imgTrajs = [];
const txtTrajs = [];

function makeTrajectory(conceptIdx, branchX, scatter, color, group) {
  const pts = [];
  for (let t = 0; t < 5; t++) {
    pts.push(conceptPos(conceptIdx, t, branchX, scatter));
  }
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineDashedMaterial({
    color: color, dashSize: 0.15, gapSize: 0.1, transparent: true, opacity: 0.6
  });
  const line = new THREE.Line(geom, mat);
  line.computeLineDistances();
  group.add(line);
  return line;
}

for (let i = 0; i < CONCEPTS.length; i++) {
  imgTrajs[i] = makeTrajectory(i, IMG_X, imgScatter, CONCEPTS[i].color, imgGroup);
  txtTrajs[i] = makeTrajectory(i, TXT_X, txtScatter, 0x888888, txtGroup);
}

// ── Arrows and boxes between planes ──
function makeArrow(x, y0, y1, group) {
  const shaftLen = (y1 - y0) * 0.5;
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.035, 0.035, shaftLen, 8),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  shaft.position.set(x, y0 + shaftLen / 2, 0);
  group.add(shaft);
  const head = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.22, 8),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  head.position.set(x, y0 + shaftLen + 0.11, 0);
  group.add(head);
}

function makeBoxLabel(x, y, text, group) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  ctx.font = 'bold 24px monospace';
  const tw = ctx.measureText(text).width + 30;
  canvas.width = Math.ceil(tw);
  canvas.height = 44;
  ctx.fillStyle = '#ffffff';
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = 3;
  const r = 12;
  ctx.beginPath();
  ctx.roundRect(2, 2, canvas.width - 4, canvas.height - 4, r);
  ctx.fill();
  ctx.stroke();
  ctx.font = 'bold 24px monospace';
  ctx.fillStyle = '#000';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';
  ctx.fillText(text, canvas.width / 2, canvas.height / 2);
  const tex = new THREE.CanvasTexture(canvas);
  tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(canvas.width / 80, canvas.height / 80, 1);
  sprite.position.set(x, y, 0);
  group.add(sprite);
  return sprite;
}

const ARROW_OFFSET = 1.6;
for (let t = 0; t < 4; t++) {
  const y0 = LAYER_Y[t] + PLANE_HH + 0.1;
  const y1 = LAYER_Y[t + 1] - PLANE_HH - 0.1;
  const midY = (y0 + y1) / 2;
  makeArrow(IMG_X - ARROW_OFFSET, y0, y1, imgGroup);
  makeBoxLabel(IMG_X - ARROW_OFFSET, midY, 'ViT block x3', imgGroup);
  makeArrow(TXT_X + ARROW_OFFSET, y0, y1, txtGroup);
  makeBoxLabel(TXT_X + ARROW_OFFSET, midY, 'transformer block x3', txtGroup);
}

// ── Orange disk ──
const diskGeom = new THREE.CircleGeometry(0.7, 48);
const diskMat = new THREE.MeshBasicMaterial({ color: 0xf4a07a, side: THREE.DoubleSide });
const disk = new THREE.Mesh(diskGeom, diskMat);
disk.position.set(0, 9.5, 0);
scene.add(disk);
const rimGeom = new THREE.RingGeometry(0.68, 0.75, 48);
const rimMat = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide });
const rim = new THREE.Mesh(rimGeom, rimMat);
rim.position.copy(disk.position);
scene.add(rim);

// ── Arrows to disk ──
function makeArrowToDisk(fromX, fromY) {
  const target = new THREE.Vector3(0, 8.9, 0);
  const start = new THREE.Vector3(fromX, fromY, 0);
  const dir = target.clone().sub(start);
  const len = dir.length() * 0.75;
  dir.normalize();
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.035, 0.035, len, 8),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  const mid = start.clone().add(dir.clone().multiplyScalar(len / 2));
  shaft.position.copy(mid);
  shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(shaft);
  const head = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.22, 8),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  const headPos = start.clone().add(dir.clone().multiplyScalar(len + 0.11));
  head.position.copy(headPos);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(head);
}
makeArrowToDisk(IMG_X + 0.5, LAYER_Y[4] + PLANE_HH + 0.15);
makeArrowToDisk(TXT_X - 0.5, LAYER_Y[4] + PLANE_HH + 0.15);

// ── Side rules with vertical text ──
function makeVerticalTextSprite(text, fontSize) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  const fs = fontSize || 28;
  ctx.font = `${fs}px sans-serif`;
  const tw = ctx.measureText(text).width;
  canvas.width = fs + 14;
  canvas.height = Math.ceil(tw) + 14;
  ctx.font = `${fs}px sans-serif`;
  ctx.fillStyle = '#000';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';
  ctx.save();
  ctx.translate(canvas.width / 2, canvas.height / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText(text, 0, 0);
  ctx.restore();
  const tex = new THREE.CanvasTexture(canvas);
  tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(canvas.width / 70, canvas.height / 70, 1);
  return sprite;
}

function makeSideRule(x, label, group) {
  const pts = [new THREE.Vector3(x, -0.5, 0), new THREE.Vector3(x, 9.0, 0)];
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  group.add(line);
  const sprite = makeVerticalTextSprite(label, 28);
  sprite.position.set(x, 4.2, 0);
  group.add(sprite);
}
makeSideRule(-5.6, 'Image encoder', imgGroup);
makeSideRule(5.6, 'Text encoder', txtGroup);

// ── Camera: front-on orthographic ──
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: null,
  heightFraction: 0.75
});

// ── Heading label ──
addLabel('Joint embedding space', new THREE.Vector3(0, 10.6, 0), { fontSize: '16px', bold: true });

// ── State ──
let currentLayer = 0;
let currentBranch = 'Both';
let hoveredConcept = -1;

const LAYER_NAMES = ['Input (L0)', 'Layer 1', 'Layer 2', 'Layer 3', 'Top (L4)'];
const BRANCH_NAMES = ['Both', 'Image only', 'Text only'];
let layerIdx = 0;
let branchIdx = 0;

function updateLayerEmphasis() {
  for (let i = 0; i < CONCEPTS.length; i++) {
    for (let t = 0; t < 5; t++) {
      const isActive = t === currentLayer;
      const isHovered = i === hoveredConcept;
      let opacity = isActive ? 1.0 : 0.35;
      let scale = isActive ? 1.3 : 1.0;
      if (isHovered) { opacity = 1.0; scale = 1.4; }
      // Image markers
      const m = imgMarkers[i][t];
      m.material.opacity = opacity;
      m.scale.setScalar(scale);
      // Text dots and labels
      const tl = txtLabels[i][t];
      tl.dot.material.opacity = opacity;
      tl.dot.scale.setScalar(scale);
      tl.entry.div.style.opacity = opacity;
      // Leader lines
      txtLeaderLines[i][t].material.opacity = isHovered ? 0.8 : (isActive ? 0.5 : 0.2);
    }
    // Trajectories
    const trajOpacity = (i === hoveredConcept) ? 1.0 : 0.45;
    imgTrajs[i].material.opacity = trajOpacity;
    txtTrajs[i].material.opacity = trajOpacity;
  }
}

function updateBranchVisibility() {
  imgGroup.visible = currentBranch !== 'Text only';
  txtGroup.visible = currentBranch !== 'Image only';
  // Also hide text labels when text branch hidden
  for (let i = 0; i < CONCEPTS.length; i++) {
    for (let t = 0; t < 5; t++) {
      txtLabels[i][t].entry.div.style.display = txtGroup.visible ? '' : 'none';
    }
  }
}

// ── UI Controls ──
const btnLayer = document.getElementById('layerStep');
btnLayer.addEventListener('click', () => {
  layerIdx = (layerIdx + 1) % 5;
  currentLayer = layerIdx;
  btnLayer.textContent = `CLIP layer: ${LAYER_NAMES[layerIdx]}`;
  updateLayerEmphasis();
});

const btnBranch = document.getElementById('branchToggle');
btnBranch.addEventListener('click', () => {
  branchIdx = (branchIdx + 1) % 3;
  currentBranch = BRANCH_NAMES[branchIdx];
  btnBranch.textContent = `Branches: ${BRANCH_NAMES[branchIdx]}`;
  updateBranchVisibility();
});

// ── Hover interaction ──
canvas.addEventListener('pointermove', (event) => {
  const entry = _firstInteractiveHit(event);
  if (entry && entry.object.userData.conceptIdx !== undefined) {
    const ci = entry.object.userData.conceptIdx;
    if (hoveredConcept !== ci) {
      hoveredConcept = ci;
